export type User = {
  id: string;
  name: string;
  email: string;
};

export type Project = {
  id: string;
  name: string;
  description: string;
  memberIds: Set<string>; // Storing as Set for easy add/remove and uniqueness
};

export type TaskStatus = 'todo' | 'in-progress' | 'done';

export type Task = {
  id: string;
  projectId: string;
  title: string;
  description: string;
  status: TaskStatus;
  assigneeId: string | null; // User ID of the assignee
};

export type Comment = {
  id: string;
  taskId: string;
  authorId: string;
  text: string;
  createdAt: number; // Timestamp
};

export type Notification = {
  id: string;
  userId: string; // Target user for this notification
  message: string;
  read: boolean;
  createdAt: number; // Timestamp
};

// Event Payloads
export type TaskAssignedEvent = {
  taskId: string;
  projectId: string;
  assigneeId: string;
  previousAssigneeId: string | null;
  timestamp: number;
};

export type TaskStatusChangedEvent = {
  taskId: string;
  projectId: string;
  previousStatus: TaskStatus;
  newStatus: TaskStatus;
  timestamp: number;
};

export type CommentAddedEvent = {
  commentId: string;
  taskId: string;
  authorId: string;
  timestamp: number;
};

export type ProjectMemberAddedEvent = {
  projectId: string;
  userId: string;
  timestamp: number;
};

export type ProjectMemberRemovedEvent = {
  projectId: string;
  userId: string;
  timestamp: number;
};

// Generic Event for EventBus
export type EventPayload =
  | TaskAssignedEvent
  | TaskStatusChangedEvent
  | CommentAddedEvent
  | ProjectMemberAddedEvent
  | ProjectMemberRemovedEvent
  | { [key: string]: any }; // Allow for other event types

export type EventCallback<T extends EventPayload = EventPayload> = (payload: T) => void;

import { EventCallback, EventPayload } from './types';

export class EventBus {
  private listeners: Map<string, Array<EventCallback<any>>> = new Map();

  public subscribe<T extends EventPayload>(eventName: string, callback: EventCallback<T>): () => void {
    if (!this.listeners.has(eventName)) {
      this.listeners.set(eventName, []);
    }
    this.listeners.get(eventName)!.push(callback);

    // Return an unsubscribe function
    return () => {
      const eventListeners = this.listeners.get(eventName);
      if (eventListeners) {
        const index = eventListeners.indexOf(callback as EventCallback<any>);
        if (index > -1) {
          eventListeners.splice(index, 1);
        }
      }
    };
  }

  public publish<T extends EventPayload>(eventName: string, payload: T): void {
    const eventListeners = this.listeners.get(eventName);
    if (eventListeners) {
      eventListeners.forEach(callback => {
        try {
          callback(payload);
        } catch (error) {
          console.error(`Error in event listener for ${eventName}:`, error);
        }
      });
    }
  }
}

import { User } from './types';

export class UserService {
  private users: Map<string, User> = new Map();

  constructor() {
    // Seed some initial data
    this.createUser({ id: 'user1', name: 'Alice Smith', email: 'alice@example.com' });
    this.createUser({ id: 'user2', name: 'Bob Johnson', email: 'bob@example.com' });
  }

  public createUser(user: User): User {
    if (this.users.has(user.id)) {
      throw new Error(`User with ID ${user.id} already exists.`);
    }
    this.users.set(user.id, user);
    return user;
  }

  public getUserById(id: string): User | undefined {
    return this.users.get(id);
  }

  public getAllUsers(): User[] {
    return Array.from(this.users.values());
  }

  public updateUser(id: string, updates: Partial<Omit<User, 'id'>>): User {
    const user = this.users.get(id);
    if (!user) {
      throw new Error(`User with ID ${id} not found.`);
    }
    const updatedUser = { ...user, ...updates };
    this.users.set(id, updatedUser);
    return updatedUser;
  }

  public deleteUser(id: string): boolean {
    return this.users.delete(id);
  }
}

import { Project, ProjectMemberAddedEvent, ProjectMemberRemovedEvent } from './types';
import { EventBus } from './eventBus';
import { v4 as uuidv4 } from 'uuid'; // Using a placeholder for uuid generation

// Placeholder for UUID generation since we cannot use npm packages
function generateUuid(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

export class ProjectService {
  private projects: Map<string, Project> = new Map();
  private eventBus: EventBus;

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;

    // Seed some initial data
    this.createProject({ id: generateUuid(), name: 'Website Redesign', description: 'Redesign the company website', memberIds: new Set(['user1']) });
    this.createProject({ id: generateUuid(), name: 'Mobile App Dev', description: 'Develop new mobile application', memberIds: new Set(['user2']) });
  }

  public createProject(project: Omit<Project, 'id' | 'memberIds'> & { id?: string; memberIds?: Set<string> }): Project {
    const newProjectId = project.id || generateUuid();
    const newProject: Project = {
      id: newProjectId,
      name: project.name,
      description: project.description,
      memberIds: project.memberIds || new Set(),
    };
    if (this.projects.has(newProject.id)) {
      throw new Error(`Project with ID ${newProject.id} already exists.`);
    }
    this.projects.set(newProject.id, newProject);
    return newProject;
  }

  public getProjectById(id: string): Project | undefined {
    return this.projects.get(id);
  }

  public getAllProjects(): Project[] {
    return Array.from(this.projects.values());
  }

  public updateProject(id: string, updates: Partial<Omit<Project, 'id' | 'memberIds'>>): Project {
    const project = this.projects.get(id);
    if (!project) {
      throw new Error(`Project with ID ${id} not found.`);
    }
    const updatedProject = { ...project, ...updates };
    this.projects.set(id, updatedProject);
    return updatedProject;
  }

  public deleteProject(id: string): boolean {
    return this.projects.delete(id);
  }

  public addMemberToProject(projectId: string, userId: string): Project {
    const project = this.projects.get(projectId);
    if (!project) {
      throw new Error(`Project with ID ${projectId} not found.`);
    }
    if (project.memberIds.has(userId)) {
      throw new Error(`User ${userId} is already a member of project ${projectId}.`);
    }
    project.memberIds.add(userId);
    this.eventBus.publish<ProjectMemberAddedEvent>('project.memberAdded', {
      projectId,
      userId,
      timestamp: Date.now(),
    });
    return project;
  }

  public removeMemberFromProject(projectId: string, userId: string): Project {
    const project = this.projects.get(projectId);
    if (!project) {
      throw new Error(`Project with ID ${projectId} not found.`);
    }
    if (!project.memberIds.has(userId)) {
      throw new Error(`User ${userId} is not a member of project ${projectId}.`);
    }
    project.memberIds.delete(userId);
    this.eventBus.publish<ProjectMemberRemovedEvent>('project.memberRemoved', {
      projectId,
      userId,
      timestamp: Date.now(),
    });
    return project;
  }

  public isProjectMember(projectId: string, userId: string): boolean {
    const project = this.projects.get(projectId);
    return project ? project.memberIds.has(userId) : false;
  }
}

import { Task, TaskStatus, TaskAssignedEvent, TaskStatusChangedEvent } from './types';
import { EventBus } from './eventBus';

// Placeholder for UUID generation
function generateUuid(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

export class TaskService {
  private tasks: Map<string, Task> = new Map();
  private eventBus: EventBus;

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;
  }

  public createTask(task: Omit<Task, 'id' | 'status'> & { id?: string; status?: TaskStatus }): Task {
    const newTaskId = task.id || generateUuid();
    const newTask: Task = {
      id: newTaskId,
      projectId: task.projectId,
      title: task.title,
      description: task.description,
      status: task.status || 'todo', // Default status is 'todo'
      assigneeId: task.assigneeId || null,
    };

    if (this.tasks.has(newTask.id)) {
      throw new Error(`Task with ID ${newTask.id} already exists.`);
    }
    this.tasks.set(newTask.id, newTask);
    return newTask;
  }

  public getTaskById(id: string): Task | undefined {
    return this.tasks.get(id);
  }

  public getTasksByProjectId(projectId: string): Task[] {
    return Array.from(this.tasks.values()).filter(task => task.projectId === projectId);
  }

  public getAllTasks(): Task[] {
    return Array.from(this.tasks.values());
  }

  public updateTask(id: string, updates: Partial<Omit<Task, 'id' | 'projectId' | 'status' | 'assigneeId'>>): Task {
    const task = this.tasks.get(id);
    if (!task) {
      throw new Error(`Task with ID ${id} not found.`);
    }
    const updatedTask = { ...task, ...updates };
    this.tasks.set(id, updatedTask);
    return updatedTask;
  }

  public deleteTask(id: string): boolean {
    return this.tasks.delete(id);
  }

  public updateTaskStatus(taskId: string, newStatus: TaskStatus): Task {
    const task = this.tasks.get(taskId);
    if (!task) {
      throw new Error(`Task with ID ${taskId} not found.`);
    }

    const currentStatus = task.status;

    // Status transition validation
    if (currentStatus === 'todo' && newStatus === 'done') {
      throw new Error("Invalid status transition: 'todo' directly to 'done' is not allowed.");
    }
    if (currentStatus === 'in-progress' && newStatus === 'todo') {
      throw new Error("Invalid status transition: 'in-progress' directly to 'todo' is not allowed.");
    }
    if (currentStatus === 'done' && (newStatus === 'todo' || newStatus === 'in-progress')) {
      throw new Error("Invalid status transition: 'done' tasks cannot be moved back to 'todo' or 'in-progress'.");
    }

    if (currentStatus !== newStatus) {
      task.status = newStatus;
      this.tasks.set(taskId, task);
      this.eventBus.publish<TaskStatusChangedEvent>('task.statusChanged', {
        taskId: task.id,
        projectId: task.projectId,
        previousStatus: currentStatus,
        newStatus: newStatus,
        timestamp: Date.now(),
      });
    }
    return task;
  }

  public assignTask(taskId: string, assigneeId: string | null): Task {
    const task = this.tasks.get(taskId);
    if (!task) {
      throw new Error(`Task with ID ${taskId} not found.`);
    }

    const previousAssigneeId = task.assigneeId;
    if (previousAssigneeId !== assigneeId) {
      task.assigneeId = assigneeId;
      this.tasks.set(taskId, task);
      this.eventBus.publish<TaskAssignedEvent>('task.assigned', {
        taskId: task.id,
        projectId: task.projectId,
        assigneeId: assigneeId,
        previousAssigneeId: previousAssigneeId,
        timestamp: Date.now(),
      });
    }
    return task;
  }
}

import { Comment, CommentAddedEvent } from './types';
import { EventBus } from './eventBus';

// Placeholder for UUID generation
function generateUuid(): string {
  return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function(c) {
    var r = Math.random() * 16 | 0, v = c == 'x' ? r : (r & 0x3 | 0x8);
    return v.toString(16);
  });
}

export class CommentService {
  private comments: Map<string, Comment> = new Map();
  private eventBus: EventBus;

  constructor(eventBus: EventBus) {
    this.eventBus = eventBus;
  }

  public createComment(comment: Omit<Comment, 'id' | 'createdAt'> & { id?: string }): Comment {
    const newCommentId = comment.id || generateUuid();
    const newComment: Comment = {
      id: newCommentId,
      taskId: comment.taskId,
      authorId: comment.authorId,
      text: comment.text,
      createdAt: Date.now(),
    };

    if (this.comments.has(newComment.id)) {
      throw new Error(`Comment with ID ${newComment.id} already exists.`);
    }
    this.comments.set(newComment.id, newComment);

    this.eventBus.publish<CommentAddedEvent>('comment.added', {
      commentId: newComment.id,
      taskId: newComment.taskId,
      authorId: newComment.authorId,
      timestamp: newComment.createdAt,
    });

    return newComment;
  }

  public getCommentById(id: string): Comment | undefined {
    return this.comments.get(id);
  }

  public getCommentsByTaskId(taskId: string): Comment[] {
    return Array.from(this.comments.values()).filter(comment => comment.taskId === taskId);
  }

  public getAllComments(): Comment[] {
    return Array.from(this.comments.values());
  }

  public deleteComment(id: string): boolean {
    return this.comments.delete(id);
  }
}
